('plschedu', 'Schedule', '<root pform="yes" name="plschedu" caption="Schedule" updatedon="26/05/2026 12:25:11" updatedby="vaidheesh" createdon="26/05/2026 12:25:11 PM" createdby="vaidheesh"><iview cat="iview" hideprojname="" hidereportdate="" parrange="1"><a0>plschedu</a0><a2>Schedule</a2><a3 ptable=""></a3><a4>0</a4><a5>true</a5><a6></a6><a7></a7><a8>0</a8><a9></a9><a10>false</a10><a11>false</a11><a12></a12><a13></a13><a14></a14><a15></a15><a16></a16><a17>Enabled</a17><a18>false</a18><a19>false</a19><a51></a51><a52></a52><a53></a53><a54></a54><a55>select row</a55><a57>false</a57><a63>true</a63><a64>false</a64><b9>plschedu</b9><b10></b10><b11></b11><b12></b12><b13></b13><b14></b14><b15></b15><b16></b16><b17></b17><b35>false</b35><b36>Center</b36><b37>Center</b37><a31></a31><a32>1</a32><a33>false</a33><a34>false</a34><a35>0</a35><a36></a36><a37></a37><a38></a38><a39>false</a39><a40>false</a40><a21>false</a21><a41>false</a41><a42>clskyblue</a42><a43>[Tahoma,9,clBlack,,True,False,False,False]</a43><a44>[Tahoma,8,clBlack,,True,False,False,False]</a44><a45>[Tahoma,8,clBlack,,True,False,False,False]</a45><a46>$00F3AFA0</a46><a47>[Tahoma,8,clBlack,,True,False,False,False]</a47><a48>$00EEF1F2</a48><a49>$00E2E8E9</a49><a50>18</a50><a60>1</a60><b18></b18><b21></b21><b23></b23><b22>0</b22><b38>Classic</b38><b39>None</b39><a65>false</a65><a66>false</a66></iview><comps cat="comps" dwbtb="true" LocalNum="9" btn="6" vupd="" pnlheight="35"><btn1 key="btn1" caption="Print" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="print" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Print" down=""><icon><text>list</text><addClass>material-icons</addClass></icon></btn1><btn2 key="btn2" caption="Preview" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="preview" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Preview" down=""><icon><text>video_label</text><addClass>material-icons</addClass></icon></btn2><btn3 key="btn3" caption="Page Setup / Printer Setting" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="printersetting" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Page Setup / Printer Setting" down=""><icon><text>import_contacts</text><addClass>material-icons</addClass></icon></btn3><btn4 key="btn4" caption="View" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="view" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="View" down=""><icon><text>remove_red_eye</text><addClass>material-icons</addClass></icon></btn4><btn5 key="btn5" caption="Find" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="find" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Find" down=""><icon><text>search</text><addClass>material-icons</addClass></icon></btn5><btn6 key="btn6" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Tasks" down="" folder="true"><icon><text>receipt</text><addClass>material-icons</addClass></icon></btn6><x__head caption="Schedule" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select a.id, a.category, a.groupid, </l0><l1>a.groupname as groupname, </l1><l2>a.mg_accountid, </l2><l3>a.accountname as accountname,</l3><l4>a.accountcode_alias, a.atype, a.alie, a.company, a.primarygroup, </l4><l5>a.pivot, </l5><l6>a.balance</l6><l7>from ( </l7><l8>select a.id, a.category, a.groupid, a.groupname, a.mg_accountid, </l8><l9>a.accountname, a.accountcode_alias, a.atype, a.alie, a.company, a.primarygroup,</l9><l10>b.period_text||''^''||b.mperiod_subtext as pivot, </l10><l11>case when ((a.alie = ''3'' and sum( b.balance) &gt; 0) or (a.alie = ''4'' and sum( b.balance) &lt; 0)) then -sum( b.balance) </l11><l12>     else abs(sum(b.balance))</l12><l13>end balance, b.ordno</l13><l14>from vw_pandlsetup a,</l14><l15>fn_accounts_balances( cast( :pcompanyid as numeric), cast( :pbranchid as numeric), cast( ''MONTHLY'' as varchar), </l15><l16>                     cast( a.mg_accountid as numeric), </l16><l17>                    cast( :pfromdate as date), cast( :ptodate as date),''T'',''F'' ) b </l17><l18>where a.company = cast( :pcompanyid as numeric) </l18><l19>and a.id not in ( 70, 130) </l19><l20>  and a.accountname = :paccountname </l20><l21>group by a.id, a.category, a.groupid, a.groupname, a.mg_accountid, a.accountname, a.accountcode_alias, a.atype, a.alie, a.company, a.primarygroup, </l21><l22>b.period_text||''^''||b.mperiod_subtext, b.ordno, a.alie</l22><l23>union all</l23><l24>select a.id, null category, 0 groupid, null groupname, 0 mg_accountid,    </l24><l25>a.accountname as accountname,   </l25><l26> null accountcode_alias, '' '' atype, '' '' alie, a.company, '' '' primarygroup, </l26><l27>b.period_text||''^''||b.mperiod_subtext as pivot, </l27><l28>case when ((''3'' = ''3'' and sum( b.balance) &gt; 0) or (''3'' = ''4'' and sum( b.balance) &lt; 0)) then -sum( b.balance) </l28><l29>     else abs(sum(b.balance))</l29><l30>end balance,</l30><l31>b.ordno</l31><l32>from vw_pandlsetup a,</l32><l33>fn_accounts_balances( cast( :pcompanyid as numeric), cast( :pbranchid as numeric), cast( ''QUARTERLY'' as varchar), cast( a.mg_accountid as numeric), </l33><l34>                    cast( :pfromdate as date), cast( :ptodate as date),''T'',''F'' ) b </l34><l35>where a.company = cast( :pcompanyid as numeric)</l35><l36>and a.id in ( 70, 130) </l36><l37>  and a.accountname = :paccountname </l37><l38>group by a.id, a.category, a.groupname, a.accountname, a.company, b.period_text||''^''||b.mperiod_subtext,b.ordno</l38><l39>) a</l39><l40>order by id, groupname, accountname, ordno</l40></a2><a3></a3><a4>reportsql</a4></row1><pcompanyid cat="params" ord="1"><a1>Task1</a1><a0>pcompanyid</a0><a2>pcompanyid</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">m_companyid</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></pcompanyid><pbranchid cat="params" ord="2"><a1>Task1</a1><a0>pbranchid</a0><a2>pbranchid</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">{99847}</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></pbranchid><pfromdate cat="params" ord="3"><a1>Task1</a1><a0>pfromdate</a0><a2>From Date</a2><a4>Date/Time</a4><a9>false</a9><a6 sugg="false">m_fystartdate</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></pfromdate><ptodate cat="params" ord="4"><a1>Task1</a1><a0>ptodate</a0><a2>To Date</a2><a4>Date/Time</a4><a9>false</a9><a6 sugg="false">m_fyenddate</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></ptodate><paccountname cat="params" ord="5"><a1>Task1</a1><a0>paccountname</a0><a2>Account Name</a2><a4>Character</a4><a9>false</a9><a6 sugg="false"></a6><a10></a10><a21>true</a21><a11>select a.accountname 
from mg_account a 
where a.alie in (''3'',''4'') 
