f="right" task="preview" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Preview" down=""><icon><text>video_label</text><addClass>material-icons</addClass></icon></btn2><btn3 key="btn3" caption="Page Setup / Printer Setting" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="printersetting" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Page Setup / Printer Setting" down=""><icon><text>import_contacts</text><addClass>material-icons</addClass></icon></btn3><btn4 key="btn4" caption="View" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="view" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="View" down=""><icon><text>remove_red_eye</text><addClass>material-icons</addClass></icon></btn4><btn5 key="btn5" caption="Find" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="find" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Find" down=""><icon><text>search</text><addClass>material-icons</addClass></icon></btn5><btn6 key="btn6" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Tasks" down="" folder="true"><icon><text>receipt</text><addClass>material-icons</addClass></icon></btn6><x__head caption="Bank / Cash Balance" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select b.accountname, sum(cast( a.native_debit - coalesce ( a.native_credit,0) as numeric)) as balance</l0><l1> from VW_ACCOUNTSDETAILS a </l1><l2>join mg_account b on a.mg_accountid = b.mg_accountid</l2><l3>where b.acatcode = ''b''</l3><l4>and a.companyid = cast( :pcompanyid as numeric)</l4><l5>and (a.branchname = :pbranch or :pbranch = ''ALL'')</l5><l6>and :ptype = ''Bank''</l6><l7>AND a.voucher_date BETWEEN cast( :pfromdate as Date) - 1 AND cast( :ptodate as Date)</l7><l8>group by b.accountname</l8><l9>UNION</l9><l10>select b.accountname, sum(cast( a.native_debit - coalesce ( a.native_credit,0) as numeric)) as balance</l10><l11>from VW_ACCOUNTSDETAILS a </l11><l12>join mg_account b on a.mg_accountid = b.mg_accountid</l12><l13>where b.acatcode = ''c''</l13><l14>and a.companyid = cast( :pcompanyid as numeric)</l14><l15>and (a.branchname = :pbranch or :pbranch = ''ALL'')</l15><l16>and :ptype = ''Cash''</l16><l17>AND a.voucher_date BETWEEN cast( :pfromdate as Date) - 1 AND cast( :ptodate as Date)</l17><l18>group by b.accountname</l18><l19>order by 1</l19></a2><a3></a3><a4>reportsql</a4></row1><pcompanyid cat="params" ord="1"><a1>Task1</a1><a0>pcompanyid</a0><a2>Company</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">m_companyid</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></pcompanyid><pbranch cat="params" ord="2"><a1>Task1</a1><a0>pbranch</a0><a2>Branch</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">{ALL}</a6><a10></a10><a21>false</a21><a11 pcount="0">select a.branchname from vw_userbranchlocations a 
where a.username = :username 
UNION
select ''ALL'' from dual
order by 1</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></pbranch><ptype cat="params" ord="3"><a1>Task1</a1><a0>ptype</a0><a2>Type</a2><a4>Character</a4><a9>false</a9><a6 sugg="false"></a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></ptype><pfromdate cat="params" ord="4"><a1>Task1</a1><a0>pfromdate</a0><a2>From Date</a2><a4>Date/Time</a4><a9>false</a9><a6 sugg="false">m_fystartdate</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></pfromdate><ptodate cat="params" ord="5"><a1>Task1</a1><a0>ptodate</a0><a2>To Date</a2><a4>Date/Time</a4><a9>false</a9><a6 sugg="false">m_fyenddate</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></ptodate><accountname cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>accountname</a2><a3>Account</a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a15>true</a15><a16>false</a16><a17>398</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></accountname><balance cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>balance</a2><a3>Balance</a3><a1>Task1</a1><a4>Numeric</a4><a5>2</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>true</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Right</a14><a15>true</a15><a16>false</a16><a17>170</a17><a18></a18><a19>false</a19><a53></a53><a54></a54>