	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a.id, a.category, </l0>
			<l1>case when a.common_intergration_code != 0 then </l1>
			<l2>''&lt;span style="margin-left: 20px;"&gt;'' || a.accountname  || ''&lt;/span&gt;''</l2>
			<l3>else</l3>
			<l4>''&lt;span style="color: maroon; text-decoration: underline; text-decoration: ''||case when a.linestyle = ''d'' then ''underline double'' else ''underline'' end</l4>
			<l5>||''; font-weight: bold;"&gt;''||a.accountname||''&lt;/span&gt;''</l5>
			<l6>end accountname,</l6>
			<l7>a.accountcode_alias, a.alie, a.common_intergration_code,  </l7>
			<l8>cast(''A''||a.id as text) groupslno, a.valexp, </l8>
			<l9>replace( a.valexp, ''amount'',''cumulative'') as valexprcumulative,</l9>
			<l10>coalesce ( fn_accounts_justbalances( cast( :pcompanyid as numeric), </l10>
			<l11>                                    cast( :pbranchid as numeric ), </l11>
			<l12>                                    a.common_intergration_code, </l12>
			<l13>                                    cast( :pfromdate as date), </l13>
			<l14>                                    cast( :ptodate as date), </l14>
			<l15>                                    cast( ''F'' as text)) </l15>
			<l16>         ) as amount, </l16>
			<l17>coalesce ( fn_accounts_justbalances( cast( :pcompanyid as numeric), cast( :pbranchid as numeric), </l17>
			<l18>                                    a.common_intergration_code, </l18>
			<l19>                                    cast( :pfromdate as date), </l19>
			<l20>                                    cast( :ptodate as date), </l20>
			<l21>                                    cast( ''T'' as text)) </l21>
			<l22>         ) as cumulative, </l22>
			<l23>a.scheduleno, </l23>
			<l24>:pbranchname as branch</l24>
			<l25>from pandl a</l25>
			<l26>order by id</l26>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
