	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select </l0>
			<l1>b.branchname,</l1>
			<l2>b.branchname as branch,</l2>
			<l3>v.vouchertype, </l3>
			<l4>:pstartdate as mstartdate, </l4>
			<l5>:penddate as menddate,</l5>
			<l6>count(1) as nostxns</l6>
			<l7>from accountshdr a, branch b, vouchertype v</l7>
			<l8>where a.cancel = ''F'' </l8>
			<l9>and a.branch = b.branchid</l9>
			<l10>and a.subtypename = v.vouchertypeid</l10>
			<l11>and </l11>
			<l12>(( :pdatecriteria = ''By Transaction Date'' and a.docdate between  cast( :pstartdate as date) and cast( :penddate as date))</l12>
			<l13>or ( :pdatecriteria =''By Posted Date'' and to_date(to_char(a.modifiedon, ''DD/MM/YYYY''), ''DD/MM/YYYY'')  between cast( :pstartdate as date) and cast( :penddate as date)))</l13>
			<l14>and (b.branchname = cast( :pbranchname as text) or </l14>
			<l15>               ( cast( :pbranchname as text)= ''ALL'' and ( cast( :pbranchlist as text) like ''%''||b.branchname||''%''  or :pbranchlist = ''ALL''  or length( :pbranchlist) = 0)) )   </l15>
			<l16>and a.company = cast( :pcompanyid as numeric)  </l16>
			<l17>and (v.vouchertype = :pvouchertype or :pvouchertype = ''ALL'')</l17>
			<l18>group by b.branchname,v.vouchertype</l18>
			<l19>order by branchname, vouchertype</l19>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
