		<x__head caption="Outstanding Customer Invoices" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/>
	</comps>
	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select </l0>
			<l1>a.arapdetailsid, </l1>
			<l2>a.sourceid, </l2>
			<l3>a.transid, </l3>
			<l4>a.mg_accountid, </l4>
			<l5>a.mg_subledgerid,  </l5>
			<l6>case when :preportby = ''By Customer'' then a.accountname else a.salesmanstate end as accountname, </l6>
			<l7>a.subledgername, </l7>
			<l8>a.branchname, </l8>
			<l9>a.salesmanstate,</l9>
			<l10>func_returns_hyperlink( a.docid,''formpage'',a.stransid,a.sourceheaderid,(select t.caption from tstructs t where t.name = a.stransid)) as docid,</l10>
			<l11>a.docid as mdocid,</l11>
			<l12>a.docdate, </l12>
			<l13>a.creditdays, </l13>
			<l14>a.due_date, </l14>
			<l15>a.amount,</l15>
			<l16>a.setamount, </l16>
			<l17>a.outstanding_amount,  </l17>
			<l18>a.outstanding_days, </l18>
			<l19>case when (a.outstanding_days &lt;= 0 or a.outstanding_amount  &lt;= 0) then a.outstanding_amount else 0 end as mslab0,  </l19>
			<l20>case when a.outstanding_days &lt;= a.mslab1 and a.outstanding_amount &gt; 0 and a.outstanding_days &gt; 0 then a.outstanding_amount  else 0 end as mslab1, </l20>
			<l21>case when a.outstanding_days between cast( :slab1 as numeric) + 1 and :slab2 and a.outstanding_amount  &gt; 0 then a.outstanding_amount else 0 end as mslab2,</l21>
			<l22>case when a.outstanding_days between cast( :slab2 as numeric) + 1 and :slab3 and a.outstanding_amount  &gt; 0 then a.outstanding_amount else 0 end as mslab3,</l22>
			<l23>case when a.outstanding_days &gt; cast( :slab3 as numeric) and a.outstanding_amount  &gt; 0 then a.outstanding_amount else 0 end as mslab4,</l23>
			<l24>case when a.outstanding_days between cast( :slab4 as numeric) + 1 and :slab5 and a.outstanding_amount  &gt; 0 then a.outstanding_amount else 0 end as mslab5,</l24>
			<l25>case when a.outstanding_days &gt; cast( :slab5 as numeric) and a.outstanding_amount  &gt; 0 then a.outstanding_amount else 0 end as mslab6</l25>
			<l26>from (</l26>
			<l27>select a.arapdetailsid, </l27>
			<l28>a.sourceid, </l28>
			<l29>substring(a.mapname FROM ''[A-Za-z]+'')as transid,  </l29>
			<l30>(select substring(e.mapname FROM ''[A-Za-z]+'') from accountsdtl d, accountshdr e where a.sourceid = d.accountsdtlid and e.accountshdrid = d.accountshdrid) as stransid,</l30>
			<l31>m.mg_accountid, </l31>
			<l32>s.mg_subledgerid,  </l32>
			<l33>(select e.sourceid from accountsdtl d, accountshdr e where a.sourceid = d.accountsdtlid and e.accountshdrid = d.accountshdrid) as sourceheaderid, </l33>
			<l34>m.accountname,</l34>
			<l35>s.subledgername, </l35>
			<l36>br.branchname, </l36>
			<l37>case when :preportby = ''By Customer'' then ''ALL'' </l37>
			<l38>     when :preportby = ''By Salesmen'' then s.salesman</l38>
			<l39>     when :preportby = ''By State/Province'' then s.statejurisdiction</l39>
			<l40>end as salesmanstate,     </l40>
			<l41>a.docid, a.docdate,</l41>
			<l42>cast( :asondate as date) as asondate,</l42>
			<l43>case when a.amount &gt; 0 then a.creditdays else 0 end as creditdays,</l43>
			<l44>case when a.amount &gt; 0 then a.docdate + interval ''1day'' * a.creditdays else a.docdate end as due_date,</l44>
			<l45>case when cast( :pcurrency as text) = ''ALL'' then a.bamount else a.namount end as amount,   </l45>
			<l46>case when cast( :pcurrency as text) = ''ALL'' then cast( a.bamount + coalesce ( b.bamount,0) as numeric) else cast( a.namount + coalesce ( b.namount,0) as numeric) </l46>
			<l47>end as outstanding_amount, </l47>
			<l48>case when cast( :pcurrency as text) = ''ALL'' then coalesce(b.bamount,0) else coalesce(b.namount,0) end as setamount,</l48>
			<l49>case when a.amount &gt; 0 then </l49>
			<l50>case when cast( :pdues as text) = ''Over Dues'' then cast( cast( :asondate as date) - cast( a.docdate + interval ''1day'' * a.creditdays as date)  as numeric)</l50>
			<l51>else  cast( :asondate as date) - a.docdate end </l51>
			<l52>else 0 end as outstanding_days,  </l52>
			<l53>cast( :slab1 as numeric) as mslab1, </l53>
			<l54>cast( :slab2 as numeric) as mslab2, </l54>
			<l55>cast( :slab3 as numeric) as mslab3, </l55>
			<l56>cast( :slab4 as numeric) as mslab4, </l56>
			<l57>cast( :slab5 as numeric) as mslab5</l57>
			<l58>from arapdetails a</l58>
			<l59>join branch br on ( a.branch = br.branchid ) </l59>
			<l60>left join (</l60>
			<l61>select b.accountname, b.subledgername, </l61>
			<l62>b.refno, max(b.refdate) as refdate, </l62>
			<l63>sum(b.amount) as amount, </l63>
			<l64>sum(b.bamount) as bamount, sum(b.namount) as namount</l64>
			<l65>from arapadjustments b </l65>
			<l66>where b.cancel = ''F''</l66>
			<l67>and b.company = cast( :pcompanyid as numeric )</l67>
			<l68>group by b.accountname, b.subledgername, b.refno</l68>
			<l69>) b on ( a.subledgercode = b.subledgername </l69>
			<l70> and a.docid = b.refno </l70>
			<l71> and a.docdate &lt;= cast( :asondate as date)</l71>
			<l72> and a.accountname = b.accountname</l72>
			<l73> )</l73>
			<l74> join mg_subledger s on ( a.subledgercode = s.mg_subledgerid  )</l74>
			<l75> join mg_account m on ( s.controlaccount = m.mg_accountid and m.acatcode = ''r'' )</l75>
			<l76> join currency c on ( m.acurrency = c.currencyid)</l76>
			<l77>where a.cancel = ''F''</l77>
			<l78>and  a.app_desc = 1</l78>
			<l79>and a.company  = cast( :pcompanyid as numeric )</l79>
			<l80>and (c.currency = cast( :pcurrency as text) or cast( :pcurrency as text) = ''ALL'')</l80>
			<l81>and (s.subledgername = cast( :pcustomer as text) or cast( :pcustomer as text) = ''ALL'')  </l81>
			<l82>and (br.branchname = cast( :pbranchname as text) or cast( :pbranchname as text) = ''ALL'') </l82>
			<l83>and a.docdate &lt;= cast( :asondate as date)</l83>
			<l84>) a</l84>
			<l85>where a.outstanding_amount != 0 </l85>
			<l86>and (a.salesmanstate = :psalesmanstate or :psalesmanstate = ''NA'' or :psalesmanstate = ''ALL'')</l86>
			<l87>order by accountname, salesmanstate, subledgername, docdate, docid</l87>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
