	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select</l0>
			<l1>	a.groupname,</l1>
			<l2>	a.accountname,</l2>
			<l3>	a.accountcode_alias,</l3>
			<l4>	sum(a.amount) as amount,	</l4>
			<l5>	a.mg_accountid,</l5>
			<l6>    cast( :pscheduleno as text) as schno, </l6>
			<l7>    ''Actmonthly,Monthly Summary,Script,calendar_month~dailysum,Daily Summary,Script,calendar_today~arapagei,Age Analysis,Script,attach_money~glsubrep,General Ledger,Script,book'' as axrowoptions,    </l7>
			<l8>    cast( :pbranchname as text) as mbranchname, </l8>
			<l9>    cast( :pfromdate as date) as mstartdate,</l9>
			<l10>    cast( :ptodate as date) as menddate    </l10>
			<l11>from</l11>
			<l12>	(	</l12>
			<l13>	select</l13>
			<l14>		b.accountname,</l14>
			<l15>		b.groupname,</l15>
			<l16>		b.mg_accountid,</l16>
			<l17>		b.accountcode_alias,</l17>
			<l18>		case</l18>
			<l19>			when b.alie = ''2'' then sum(b.base_debit-b.base_credit)*(1-2)</l19>
			<l20>			else sum(b.base_debit-b.base_credit)</l20>
			<l21>		end as amount</l21>
			<l22>	from</l22>
			<l23>		vw_accounttreelink a,</l23>
			<l24>		mv_accountsdetails b</l24>
			<l25>	where</l25>
			<l26>		a.parantid in (</l26>
			<l27>		select</l27>
			<l28>			a.accountname</l28>
			<l29>		from</l29>
			<l30>			vw_parantlink a</l30>
			<l31>		where</l31>
			<l32>			(( a.common_intergration_code = cast( :pcommonintegratiocode as numeric) or a.common_intergration_code1 = cast( :pcommonintegratiocode as numeric) </l32>
			<l33>			  or a.common_intergration_code2 = cast( :pcommonintegratiocode as numeric)) </l33>
			<l34>				or cast( :pcommonintegratiocode as numeric) = 0)</l34>
			<l35>				and a.company = cast( :pcompanyid as numeric) )</l35>
			<l36>		and a.parantid = b.mg_accountid</l36>
			<l37>		and b.company = cast( :pcompanyid as numeric)</l37>
			<l38>		and ( b.branchid = cast( :pbranchid as numeric) or (cast( :pbranchid as numeric) = 0 or cast( :pbranchid as numeric) = 1))</l38>
			<l39>		and  b.voucher_date &lt;= cast( :ptodate as date)</l39>
			<l40>	group by</l40>
			<l41>		b.accountname,</l41>
			<l42>		b.groupname,</l42>
			<l43>		b.alie,</l43>
			<l44>		b.mg_accountid,</l44>
			<l45>		b.accountcode_alias		</l45>
			<l46>		) a</l46>
			<l47>group by</l47>
			<l48>	a.accountname,</l48>
			<l49>	a.groupname,</l49>
			<l50>	a.mg_accountid,</l50>
			<l51>	a.accountcode_alias</l51>
			<l52>order by</l52>
			<l53>	groupname,</l53>
			<l54>	accountname</l54>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
