><btn3 key="btn3" caption="Page Setup / Printer Setting" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="printersetting" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Page Setup / Printer Setting" down=""/><btn4 key="btn4" caption="View" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="view" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="View" down=""/><btn5 key="btn5" caption="Find" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="find" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Find" down=""/><btn6 key="btn6" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Tasks" down="" folder="true"/><x__head caption="GST Percentagewise Report" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select branchname,placeofsupply,taxper,</l0><l1>case when supplytype in ( ''Inter State'','''') then sum(taxableamount) end as igst,</l1><l2>case  when supplytype = ''Intra State'' then sum(taxableamount)/2 end as cgst,</l2><l3>case when supplytype = ''Intra State'' then sum(taxableamount)/2 end as sgst,</l3><l4>supplytype,sum(grossamount) as grossamount,sum(taxableamount) as taxableamount,sum(netamount) as netamount</l4><l5>from (</l5><l6>select ''t''||sh.transid as stransid,b.branchname ,sh.docid voucher_number, sh.docdate voucher_date,</l6><l7>case when sh.transid!= ''incdv''then sh.newcustomer else j.party_name end as newcustomer,</l7><l8>sh.supply_type supplytype,upper(trim(sh.state)) placeofsupply,sh2.itemname,i.itemdesc ,i.hsnno,sh.gstnumber gstno,sh2.taxcategory,sh2.taxper,</l8><l9>sh2.taxableamount  ,sh2.net_amount  grossamount,sh2.gross_afterdiscount netamount,sh.irn_generated</l9><l10>from salesinvoice_header sh join salesinvoice_items  sh2 on sh.salesinvoice_headerid =sh2.salesinvoice_headerid </l10><l11>left join vw_item i on sh2.itemname =i.itemid join branch b on sh.branch =b.branchid</l11><l12>left join (select mp.party_name,sh.salesinvoice_headerid  from salesinvoice_header sh </l12><l13>left join mg_partyhdr mp on sh.customer = mp.mg_partyhdrid </l13><l14>where sh.transid =''incdv'') j on sh.salesinvoice_headerid = j.salesinvoice_headerid</l14><l15>where sh.cancel =''F'' and sh.app_desc = 1 </l15><l16>and sh.company = :company</l16><l17>and (b.branchname = :branch or ''ALL'' = :branch )</l17><l18>and sh.docdate between :fdate and :tdate</l18><l19>union all</l19><l20>select  ''t''||sh.transid as stransid,b.branchname ,sh.docid voucher_number, sh.docdate voucher_date,</l20><l21>sh.newcustomer ,</l21><l22>sh.supply_type supplytype,upper(trim(sh.state)) placeofsupply,0 itemname,''Shipping'' itemdesc,sh.shipping_hsnno hsnno,sh.gstnumber gstno,sh.taxper_shipping taxcat,</l22><l23>sh.shipping_taxrate taxper,shipping_taxamount   taxableamount, sh.shipping_netamount  grossamount,sh.shipping_charges netamount,sh.irn_generated</l23><l24>from salesinvoice_header sh join branch b on sh.branch =b.branchid </l24><l25>where shipping_charges &lt;&gt;0 </l25><l26>and sh.cancel =''F'' and sh.app_desc = 1 </l26><l27>and sh.company = :company</l27><l28>and (b.branchname = :branch or ''ALL'' = :branch )</l28><l29>and sh.docdate between :fdate and :tdate</l29><l30>union all</l30><l31>select ''tinstk'' as stransid,d2.branchname branch,a.docid voucher_number,a.docdate voucher_date,</l31><l32>d2.branchname as newcustomer,</l32><l33>a.supplytype supplytype,upper(trim(d2.state)) placeofsupply,</l33><l34>i.itemid itemname,i.itemdesc,i.hsnno ,d2.tinno gstno,b.taxcategory taxcat,b.taxper taxper,</l34><l35>b.taxableamount taxableamount,b.gross_amount grossamount,b.issue_amount netamount,a.irn_generated</l35><l36>from stockissues_header a join stockissues_items b on a.stockissues_headerid =b.stockissues_headerid </l36><l37>join vw_item i on b.itemname =i.itemid join branch d on a.branch=d.branchid join branch d2 on a.tobranch = d2.branchid </l37><l38>where a.cancel =''F'' and a.app_desc = 1 </l38><l39>and a.company = :company</l39><l40>and (d.branchname = :branch or ''ALL'' = :branch )</l40><l41>and a.docdate between :fdate and :tdate</l41><l42>and a.issuetypecode =''5''</l42><l43>union all </l43><l44>select ''t''||a.transid as stransid,d.branchname branchname,a.docid voucher_number,a.docdate voucher_date,</l44><l45>a.customer as newcustomer,</l45><l46>a.supply_type supplytype,upper(trim(d.state)) state,i.itemid itemname,i.itemdesc</l46><l47>,i.hsnno,a.gstnumber gstno,b.extaxcategory  taxcat,b.extaxper  taxper,</l47><l48>b.extaxableamount  taxableamount, b.exnet_amount grossamount,</l48><l49>b.exgross_amount netamount,''F'' irn_generated from salesreturns_header  a join sales_exchangeitems b on a.salesreturns_headerid =b.salesreturns_headerid</l49><l50>join vw_item i on b.exitemname =i.itemid join branch d on a.branch=d.branchid</l50><l51>where a.cancel =''F'' and a.app_desc = 1 </l51><l52>and a.company = :company</l52><l53>and (d.branchname = :branch or ''ALL'' = :branch )</l53><l54>and a.docdate between :fdate and :tdate</l54><l55>union all</l55><l56>select ''t''||a.transid as stransid,d.branchname branch,a.docid voucher_number,a.docdate voucher_date,</l56><l57>a.customer as newcustomer,</l57><l58>a.supply_type supplytype,upper(trim(d.state)) state,0 itemname,''shipping'' itemdesc ,</l58><l59>'''' hsnno, a.gstnumber gstno,a.taxper_shipping taxcat,cast(regexp_replace(a.taxper_shipping,''[^0-9]+'','''',''g'') as numeric) taxper,</l59><l60> round(a.addshippingcharges - a.addshippingcharges * 100::numeric / (100::numeric + max(b_1.extaxper)))  taxableamount,</l60><l61> a.addshippingcharges - round(a.addshippingcharges - a.addshippingcharges * 100::numeric / (100::numeric + max(b_1.extaxper))) grossamount,a.addshippingcharges netamount,''F'' irn_generated</l61><l62>from salesreturns_header a join branch d on a.branch=d.branchid </l62><l63>JOIN sales_exchangeitems b_1 ON a.salesreturns_headerid = b_1.salesreturns_headerid</l63><l64>where a.addshippingcharges &lt;&gt;0 and a.addshippingcharges is not null</l64><l65>and a.cancel =''F'' and a.app_desc = 1 </l65><l66>and a.company = :company</l66><l67>and (d.branchname = :branch or ''ALL'' = :branch )</l67><l68>and a.docdate between :fdate and :tdate</l68><l69>group by a.transid,d.branchname ,a.docid,a.docdate ,a.customer,a.supply_type,d.state,a.taxper_shipping,a.addshippingcharges,</l69><l70>exchangeshippinggross,a.addshippingcharges,a.gstnumber</l70><l71>union all</l71><l72>select ''t''||a.transid as stransid,d.branchname branch,a.docid voucher_number,a.docdate vouche_date,</l72><l73>a.customer as newcustomer,</l73><l74>a.supply_type supplytype,d.state state,i.itemid itemname,i.itemdesc ,i.hsnno,a.gstnumber gstno,b.taxcategory taxcat,b.taxper taxper,</l74><l75>-b.taxableamount taxableamount,-b.net_amount grossamount,-b.gross_amount netamount,''F'' irn_generated</l75><l76>from salesreturns_header a,salesreturns_items   b,branch d,vw_item i</l76><l77>where a.salesreturns_headerid = b.salesreturns_headerid </l77><l78>and a.branch = d.branchid</l78><l79>and b.itemname =i.itemid </l79><l80>and  a.cancel = ''F''</l80><l81>and a.app_desc = 1 </l81><l82>and a.company = :company</l82><l83>and (d.branchname = :branch or ''ALL'' = :branch )</l83><l84>and a.docdate between :fdate and :tdate</l84><l85>union all</l85><l86>select ''t''||a.transid as stransid,d.branchname branch,a.docid voucher_number,a.docdate vouche_date,</l86><l87>a.customer as newcustomer,</l87><l88>a.supply_type supplytype,d.state state,0 as itemname,''Shipping'' as itemdesc,</l88><l89>'''' hsnno,a.gstnumber gstno,a.taxper_shipping  taxcat,a.shippingtaxrate  taxper</l89><l90>,-round(a.reverseshipping - a.reverseshipping * 100::numeric / (100::numeric +  max(b.taxper))) taxableamount,</l90><l91>-(a.reverseshipping -round(a.reverseshipping - a.reverseshipping * 100::numeric / (100::numeric +  max(b.taxper))) ) as  grossamount,</l91><l92>-a.reverseshipping netamount,''F'' irn_generated </l92><l93>from salesreturns_header a,branch d,salesreturns_items b</l93><l94>where a.reverseshipping &gt; 0</l94><l95>and a.salesreturns_headerid = b.salesreturns_headerid </l95><l96>and a.company = :company</l96><l97>and a.branch = d.branchid</l97><l98>and (d.branchname = :branch or ''ALL'' = :branch ) </l98><l99>and a.docdate between :fdate and :tdate</l99><l100>group by a.transid ,d.branchname ,a.docid ,a.docdate,a.customer ,a.supply_type,d.state,a.taxper_shipping,a.shippingtaxrate,</l100><l101>a.reverseshipping,a.returnshippinggross,a.gstnumber</l101><l102>order by 2,3</l102><l103>) a</l103><l104>where (case when length(gstno) = ''15'' then ''Registered''   else ''UnRegistered'' end  = :gsttype or ''ALL''=:gsttype)</l104><l105>and (supplytype =:stype or ''ALL'' = :stype) </l105><l106>group by branchname,placeofsupply,supplytype,taxper</l106></a2><a3></a3><a4>reportsql</a4></row1><company cat="params" ord="1"><a1>Task1</a1><a0>company</a0><a2>company</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">m_companyid</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></company><branch cat="params" ord="2"><a1>Task1</a1><a0>branch</a0><a2>SBU/Branch</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">m_branch</a6><a10></a10><a21>false</a21><a11 pcount="0">select a.branchname branchname
from vw_userbranchlocations a    
where a.username = :username 
