('{A2E82578-B98F-4895-9073-22B05D9AC430}', '2026-05-22 13:43:26+05:30', 'Unknown', '{"_parameters":[{"getsqldata":{"axpapp":"erpgolddemo","sqlname":"","sqltext":"select 
concat(a.accountname,&apos; (&apos;, a.accountcode,&apos;)&apos;) accountname,
concat(&apos;&quot;EntityForm.aspx?tstid=&apos;,a.transid,&apos;&amp;recid=&apos;,cast (a.mg_accountid as varchar),&apos;&quot;&apos;) as link,
a.groupname, 
a.atype,
a.grplevel,
case when a.grplevel = 0 then &apos;&apos; else a.acategory end as acategory,
coalesce (b.OP,0) as opbal,
coalesce (b.TRADB,0) as debit,
coalesce (b.TRACR,0) as credit,
coalesce (b.CL,0) as clbal, a.applicablebranches, 
a.accountname as accountnameparam, 
concat(a.groupname,&apos; (&apos;, a.groupcode,&apos;)&apos;) as groupnamewithcode,
case when upper(A.ACCOUNT) in (&apos;ASSETS&apos;,&apos;LIABILITIES&apos;,&apos;INCOME&apos;,&apos;EXPENSES&apos;) then 
	concat(&apos;&lt;span style=&quot;font-weight:bold;&quot;&gt;&lt;u&gt;&apos;, a.account, &apos;&lt;/u&gt;&lt;/span&gt;&apos;)
	when upper(a.atype) = &apos;GROUP&apos; then concat(&apos;&lt;span style=&quot;font-weight:bold;&quot;&gt;&apos;, a.account, &apos;&lt;/span&gt;&apos;)
    when upper(a.atype) = &apos;GROUP&apos; then upper(a.account)
else
    initcap(a.ACCOUNT) 
end as sampletree, 
case when a.grplevel = 0 then &apos;F&apos; else &apos;T&apos; end as editable,  
case when a.atype = &apos;Group&apos; then &apos;&lt;span class=&quot;material-icons material-icons-style&quot;&gt;folder_open&lt;/span&gt;&apos;
else 
	case  
     	 when a.acategory = &apos;Fixed Asset&apos; then  &apos;&lt;span class=&quot;material-icons material-icons-style&quot;&gt;apartment&lt;/span&gt;&apos;
		 when a.acategory = &apos;Cash Book&apos; then &apos;&lt;span class=&quot;material-icons material-icons-style&quot;&gt;payments&lt;/span&gt;&apos;
		 when a.acategory = &apos;Bank Book&apos; then &apos;&lt;span class=&quot;material-icons material-icons-style&quot;&gt;domain&lt;/span&gt;&apos;
		 when a.acategory = &apos;Receivable A/c&apos; then &apos;&lt;span class=&quot;material-icons material-icons-style&quot;&gt;call_received&lt;/span&gt;&apos;	 
		 when a.acategory = &apos;Payable A/c&apos; then	&apos;&lt;span class=&quot;material-icons material-icons-style&quot;&gt;call_made&lt;/span&gt;&apos; 
		 when a.acategory = &apos;Stock A/c&apos; then &apos;&lt;span class=&quot;material-icons material-icons-style&quot;&gt;inventory&lt;/span&gt;&apos;
		 else &apos;&lt;span class=&quot;material-icons material-icons-style&quot;&gt;account_balance&lt;/span&gt;&apos;
	end 
end	as micons, 
a.controlaccount as subledgerflag
from fn_account_tree( cast( :m_companyid as numeric))  a	
left outer join (
select
		PARANTID,
		SUM (OP) as OP,
		SUM (TRADB) as TRADB,
		SUM (TRACR) as TRACR,
		SUM (OP + TRADB - TRACR) as CL
	from
		(		
		select
			A.PARANTID,
			(b.base_debit - b.base_credit) * case
				when b.alie in (&apos;2&apos;, &apos;3&apos;) then 1-2
				else 1
			end as op,
			0 as TRADB,
			0 as TRACR
		from
			VW_ACCOUNTTREELINK A,
			mv_accountmonthlysummary B
		where
			A.CHILDID = B.mg_accountid
			and B.financial_year = :m_finyr
			and (b.base_debit - b.base_credit) &lt;&gt; 0
			and b.company = cast( :m_companyid as numeric) 	
	union all
	select A.PARANTID,
			0 as OP,
			b.base_debit  as TRADB,
			b.base_credit  as TRACR
		from
			VW_ACCOUNTTREELINK A,
			mv_accountmonthlysummary B
		where		
			A.CHILDID = B.mg_accountid
			and B.financial_year = :m_finyr
			and b.company = cast( :m_companyid as numeric) 
				) a
	group by
		PARANTID
		) B on	
A.mg_accountid  = B.PARANTID 
order by aprefix, sno
