('{37D7B968-0E39-4F42-B8E2-C72A1B2FF07B}', '2026-05-26 17:54:10+05:30', 'Unknown', '{"_parameters":[{"getsqldata":{"axpapp":"erpgolddemo","sqlname":"","sqltext":"select i.itemcode, i.itemname, a.locationname, a.branchname,
a.vouchertype,  
a.docdate, 
a.docid,  
&apos;t&apos;||case WHEN a.mapname IS NOT NULL THEN cast(regexp_replace(a.mapname, &apos;[0-9]+&apos;, &apos;&apos;, &apos;g&apos;) as text) ELSE &apos;stock&apos; end as transid,
a.username, 
a.createdon,
a.createdby,
a.modifiedon,
a.issued_qty as issued_qty, 
a.issued_value as issued_vlu,
a.received_qty as received_qty,
a.received_value received_vlu,
a.received_qty + a.issued_qty as closing_qty,
a.received_value + a.issued_value as closing_value,
a.rate
from
( select a.itemid itemname, a.locationname, a.branchname, a.company, 
&apos;Opening Balance&apos; vouchertype, 
cast( :pfromdate as date) AS docdate, 
&apos;Opening Bal.&apos; AS docid, 
NULL AS mapname, 
NULL username, 
cast(null as date)  as createdon,cast(null as date) AS modifiedon,min(a.createdby) AS createdby,
&apos;p&apos; AS plusorminus,
0 issued_qty, 0 AS issued_value, sum(a.received_qty + a.issued_qty) as received_qty,sum(a.received_value + a.issued_value) AS received_value, 
CASE WHEN sum(a.received_qty + a.issued_qty) &gt;  0 THEN sum(a.received_value + a.issued_value) / sum(a.received_qty + a.issued_qty) ELSE 0 END AS rate    
from mv_stockdetails a
where  a.cancel = &apos;F&apos; and a.docdate &lt; cast( &apos;26/05/2026&apos; as date)
group by a.itemid, a.branchname, a.company,a.locationname
union all
select a.itemid itemname, a.locationname, a.branchname, a.company, 
a.vouchertype,  
a.docdate, 
a.docid,
a.mapname, 
a.username, 
a.createdon,a.modifiedon,a.createdby,
a.plusorminus,
a.issued_qty,
a.issued_value,
a.received_qty,
a.received_value, 
a.rate 
from mv_stockdetails a
where a.cancel = &apos;F&apos; and a.docdate between cast( &apos;26/05/2026&apos; as date)  and cast( &apos;26/05/2026&apos; as date)
) a, item i
where a.itemname = i.itemid
and i.itemid != 1
and a.company = cast( 1039440000000 as numeric)
and (a.branchname  = &apos;HEAD OFFICE&apos; or &apos;ALL&apos; = &apos;HEAD OFFICE&apos; )
and (a.locationname  = &apos;ALL&apos; or &apos;ALL&apos; = &apos;ALL&apos; )
and (i.itemdesc = &apos;ALL&apos; or &apos;ALL&apos; = &apos;ALL&apos;)
order by a.branchname, a.locationname, i.itemname, docdate, createdon nulls first","isdropdown":"f","sqlcols":"f","trace":"true"},"erpgolddemo":{
