('{7239D8FB-C9EA-4405-A6B2-344A076E5D74}', '2026-06-04 16:25:08+05:30', 'Unknown', '{"_parameters":[{"getsqldata":{"axpapp":"erpgolddemo","sqlname":"","sqltext":"select a.name, a.value, a.link from 
(select &apos;Sales&apos; as name,COALESCE (case WHEN sum(a.total_sales_amount) &gt; 1000000 THEN round(sum(a.total_sales_amount) / 1000000,2) || &apos; M&apos; 
WHEN sum(a.total_sales_amount) &lt; 1000000 and sum(a.total_sales_amount) &gt; 0 THEN TO_CHAR(sum(a.total_sales_amount), &apos;FM999,999,999,999&apos;)
WHEN SUM(a.total_sales_amount) &lt;= -1000000 THEN  ROUND(abs(SUM(a.total_sales_amount)) / 1000000, 2) || &apos; M&apos;
ELSE TO_CHAR(Abs(sum(a.total_sales_amount)), &apos;FM999,999,999,999&apos;) end,&apos;NIL&apos;) as value, &apos;iitmsals()&apos; as link,1 as ord
from vw_sales_header a
--WHERE a.company = cast( :m_companyid as numeric)
--and a.docdate between cast( :m_fystartdate as date) AND cast( :m_fyenddate as date)
union
select &apos;Pending Sales Order&apos; as name,COALESCE ( cast(COUNT(1) as varchar), &apos;NIL&apos;) as value ,&apos;iivsor()&apos; as link ,2 as ord
from salesorder_header a ,salesorder_items b 
where a.cancel = &apos;F&apos;
and a.app_desc = 1 
and b.salesorder_headerid = a.salesorder_headerid
--and a.company = cast( :m_companyid as numeric)
--AND a.docdate BETWEEN :m_fystartdate AND :m_fyenddate
and (b.order_qty - b.invoiced_qty) &gt; 0
union
SELECT &apos;Receivables&apos; as name,COALESCE ( case WHEN sum(cast( (a.bamount + COALESCE(b.bamount, 0)) AS numeric)) &gt; 1000000 
THEN round(sum(cast( (a.bamount + COALESCE(b.bamount, 0)) AS numeric)) / 1000000,2) || &apos; M&apos; 
WHEN sum(cast( (a.bamount + COALESCE(b.bamount, 0)) AS numeric)) &lt; 1000000 and sum(cast( (a.bamount + COALESCE(b.bamount, 0)) AS numeric)) &gt; 0 
THEN TO_CHAR(sum(cast( (a.bamount + COALESCE(b.bamount, 0)) AS numeric)), &apos;FM999,999,999,999&apos;)
WHEN sum(cast( (a.bamount + COALESCE(b.bamount, 0)) AS numeric)) &lt;= -1000000 
THEN  ROUND(abs(sum(cast( (a.bamount + COALESCE(b.bamount, 0)) AS numeric))) / 1000000, 2) || &apos; M&apos;
ELSE TO_CHAR(abs(sum(cast( (a.bamount + COALESCE(b.bamount, 0)) AS numeric))), &apos;FM999,999,999,999&apos;) end, &apos;NIL&apos;) as value, &apos;iaccrecv()&apos; as link ,3 as ord
FROM arapdetails a
join branch br on br.branchid = a.branch
LEFT JOIN arapadjustments b ON (
    a.subledgercode = b.subledgername 
    AND a.docid = b.refno 
    AND a.accountname = b.accountname
    AND b.cancel = &apos;F&apos;
)
JOIN mg_account m ON (
    a.accountname = m.mg_accountid  
    AND m.controlaccount = &apos;T&apos; 
    AND m.acatcode = &apos;r&apos;
)
WHERE a.cancel = &apos;F&apos;
AND a.app_desc = 1
--AND a.company = CAST( :m_companyid AS numeric)
--AND a.docdate &lt;= :m_fyenddate
union
SELECT &apos;Sales Returns&apos; as name,COALESCE ( case WHEN sum(a.total_sales_amount) &gt; 1000000 THEN round(sum(a.total_sales_amount) / 1000000,2) || &apos; M&apos; 
WHEN sum(a.total_sales_amount) &lt; 1000000 and sum(a.total_sales_amount) &gt; 0 THEN TO_CHAR(sum(a.total_sales_amount), &apos;FM999,999,999,999&apos;)
WHEN SUM(a.total_sales_amount) &lt;= -1000000 THEN  ROUND(SUM(a.total_sales_amount) / 1000000, 2) || &apos; M&apos;
ELSE TO_CHAR(abs(sum(a.total_sales_amount)), &apos;FM999,999,999,999&apos;) end, &apos;NIL&apos;) AS value, &apos;isalrtrp()&apos; as link,4 as ord
FROM salesreturns_header a 
WHERE a.cancel = &apos;F&apos;
AND a.app_desc = 1
--AND a.company = CAST( :m_companyid AS numeric)
--AND a.branch = CAST( :m_branchid AS numeric)
--AND a.docdate BETWEEN :m_fystartdate AND :m_fyenddate)a
order by ord","isdropdown":"f","sqlcols":"f","trace":"true"},"erpgolddemo":{
