urpose":""},{"tstruct":"axfin","dname":"dc2","caption":"Periods","tablename":"financialyeardtl","asgrid":"T","allowchange":"T","allowempty":"T","popup":"F","dcno":"2","addrow":"T","deleterow":"T","createdby":"","createdon":"","modifiedby":"","modifiedon":"","purpose":"-- fill grid query,removed on 17/11/15\r\nselect ''00'' periodcode, to_char( :startdate ,''YYYY - '')||''00'' perioddesc, ''Q0'' quarter, ( \r\n:startdate - 1) pstartdate, ( :startdate - 1)  penddate  \r\nfrom dual\r\nunion all\r\nselect lpad(level,2,''0'') periodcode, \r\nto_char(add_months( :startdate, level-1),''YYYY - MM'') perioddesc, \r\ncase when level<=3 then ''Q1'' \r\nwhen level between 4 and 6 then ''Q2'' \r\nwhen level between 7 and 9 then ''Q3'' else ''Q4'' end quarter, \r\nadd_months( :startdate, level-1) pstartdate, \r\nadd_months( :startdate, level)-1 penddate\r\nFROM Dual CONNECT BY Level <= MONTHS_BETWEEN( :enddate , :startdate ) + 1\r\nunion all\r\nselect ''99'' periodcode, to_char( :startdate ,''YYYY - '')||''99'' perioddesc, ''Q9'' quarter,  \r\n:enddate pstartdate, :enddate penddate \r\nfrom dual\r\norder by periodcode\r\n\r\n"},{"tstruct":"axerr","dname":"dc1","caption":"Custom Error Messages","tablename":"AXCONSTRAINTS","asgrid":"F","allowchange":"T","allowempty":"T","popup":"F","dcno":"1","addrow":"T","deleterow":"T","createdby":"","createdon":"","modifiedby":"","modifiedon":"","purpose":""},{"tstruct":"appsr","dname":"dc1","caption":"dc1","tablename":"axp_appsearch_data","asgrid":"F","allowchange":"T","allowempty":"T","popup":"F","dcno":"1","addrow":"T","deleterow":"T","createdby":"","createdon":"","modifiedby":"","modifiedon":"","purpose":""},{"tstruct":"appsr","dname":"dc2","caption":"Params -  ({rowcount})","tablename":"axp_appsearchdtl","asgrid":"T","allowchange":"T","allowempty":"T","popup":"F","dcno":"2","addrow":"T","deleterow":"T","createdby":"","createdon":"","modifiedby":"","modifiedon":"","purpose":""},{"tstruct":"appsr","dname":"dc3","caption":"Param String","table